	/**
	 * Creates the provided command.
	 *
	 * @param		command ${class.getCreateCommandAlias()}
	 * @return		IoTDevice
	 */
		public IoTDevice createIoTDevice( CreateIoTDeviceCommand command ) {

		IoTDevice entity = new IoTDevice();

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

            entity.setIoTDeviceId( command.getIoTDeviceId() );
            entity.setDeviceId( command.getDeviceId() );
            entity.setSerialNumber( command.getSerialNumber() );
            entity.setLastSeen( command.getLastSeen() );
            entity.setFirmwareVersion( command.getFirmwareVersion() );
            entity.setStatus( command.getStatus() );
            entity.setPowerSource( command.getPowerSource() );

		// ------------------------------------------
		// persist a new one
		// ------------------------------------------
		entity = projector.create(entity);

		LOGGER.info( "done creating of IoTDevice {0} ", entity.toString() );

		return entity;
	}

